'use strict';
const $=(q,root=document)=>root.querySelector(q);
const $$=(q,root=document)=>[...root.querySelectorAll(q)];
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const S={boot:null,user:null,authRole:location.pathname==='/recruiter'?'recruiter':'candidate',register:false,
  view:'dashboard',tab:'applications',application:null,step:0,pool:null,job:'demo-campaign',search:'',filter:'all',sort:'score',reviewTab:'evidence',rotation:42,ai:null};
let saveTimer=null,saveChain=Promise.resolve(),toastTimer=null,recorder=null,recordStream=null,recordTimeout=null;
const colors=['#187d71','#347cb8','#8061bf','#c68a2b','#bc5965'];
const statusTag=s=>`<span class="tag ${['interview'].includes(s)?'green':['submitted','draft'].includes(s)?'gray':s==='not_proceeding'||s==='withdrawn'?'red':s==='invited'?'orange':''}">${esc(S.boot?.statuses[s]||s)}</span>`;
const initials=name=>esc((name||'?').split(/\s+/).slice(0,2).map(x=>x[0]).join('').toUpperCase());
const date=s=>s?new Date(s).toLocaleString(undefined,{month:'short',day:'numeric',hour:'numeric',minute:'2-digit'}):'—';
const wordmark='<span class="wordmark">evidence<span>path</span></span>';
const button=(label,action,extra='',kind='primary')=>`<button type="button" class="btn ${kind}" data-action="${action}" ${extra}>${label}</button>`;

async function api(path,data,options={}){
  const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),45000);
  try{
    const r=await fetch(path,{method:data===undefined?'GET':'POST',credentials:'same-origin',signal:controller.signal,
      headers:data===undefined?{'X-Workspace':S.user?.role||S.authRole}:{'Content-Type':'application/json','X-Evidence-Path':'1','X-Workspace':S.user?.role||S.authRole},body:data===undefined?undefined:JSON.stringify(data),...options});
    const value=await r.json();
    if(!r.ok){if(r.status===401&&S.user){S.user=null;S.application=null;render();}throw new Error(value.error||'The request could not be completed.');}
    return value;
  }catch(error){if(error.name==='AbortError')throw new Error('The request took too long. Your last saved work remains available.');throw error;}
  finally{clearTimeout(timer);}
}
function toast(message,error=false){const t=$('#toast');t.textContent=message;t.hidden=false;t.className='toast'+(error?' error-toast':'');clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.hidden=true,error?8000:4500);}
function busy(el,yes){if(!el)return;el.disabled=yes;if(yes){el.dataset.label=el.innerHTML;el.innerHTML='<span class="spinner" aria-hidden="true"></span> Working…';}else if(el.dataset.label)el.innerHTML=el.dataset.label;}
function field(label,name,value='',hint='',answer=false,short=false){return `<label class="field"><span>${esc(label)}</span><textarea ${answer?'data-answer':'data-field'}="${name}" class="${short?'short':''}" maxlength="${name.endsWith('_text')?24000:12000}">${esc(value)}</textarea>${hint?`<small>${esc(hint)}</small>`:''}</label>`;}
function loading(message='Opening your workspace…'){$('#root').innerHTML=`<main id="main" class="loading">${wordmark}<p class="muted">${esc(message)}</p></main>`;}
function render(){if(!S.user)return auth();if(S.user.role==='candidate')renderCandidate();else renderRecruiter();}

function auth(){
  const candidate=S.authRole==='candidate';
  $('#root').innerHTML=`<div class="landing"><section class="landing-left"><div>${wordmark}</div><div class="stack"><span class="eyebrow">Beyond the application</span><h1>Let the evidence<br>speak for you.</h1><p>A space to explain your experience, show your approach and keep the conversation grounded in your work.</p><div class="landing-quote">A decision story gives context.<br>A practical task gives another perspective.</div></div><div class="local">Local prototype · your computer</div></section><main id="main" class="landing-right"><div class="auth-form stack"><div class="role-tabs" role="group" aria-label="Workspace"><button class="${candidate?'active':''}" data-action="auth-role" data-value="candidate">Candidate</button><button class="${!candidate?'active':''}" data-action="auth-role" data-value="recruiter">Recruiter</button></div><div class="stack"><div><h2>${candidate?(S.register?'Your next opportunity starts here.':'Welcome to your workspace.'):'A clearer view of your candidate pool.'}</h2><p class="muted small">${candidate?'Your experience, your decisions, your evidence.':'Review the evidence. Keep the decision in human hands.'}</p></div><form id="auth-form" class="stack">${candidate&&S.register?'<label class="field"><span>Your name or test alias</span><input name="name" autocomplete="name" maxlength="120" required></label>':''}<label class="field"><span>Username</span><input name="username" autocomplete="username" autocapitalize="none" required maxlength="80" placeholder="${candidate?'Choose a username':'recruiter'}"></label><label class="field"><span>Password</span><input name="password" type="password" autocomplete="${S.register?'new-password':'current-password'}" required ${S.register?'minlength="8"':''}></label><div id="auth-error" class="auth-error error" role="alert"></div><button class="btn primary" type="submit">${candidate&&S.register?'Create candidate account':'Sign in'}</button></form><div class="auth-links">${candidate?`<button data-action="auth-toggle">${S.register?'Already have an account? Sign in':'New here? Create an account'}</button><button data-action="demo-login">Start guided candidate demo</button>`:'<span class="muted">Your generated recruiter password is in <strong>data/.local-access.txt</strong> inside the application folder.</span>'}</div></div></div><div class="local-note">This working prototype runs on this computer. No external AI service is connected. Recruiters can optionally enable an installed local model. Use fictional information when exploring the sample campaign.</div></main></div>`;
  $('#auth-form').onsubmit=async event=>{event.preventDefault();const el=$('button[type=submit]',event.target);busy(el,true);$('#auth-error').textContent='';try{const data=Object.fromEntries(new FormData(event.target));const r=await api(S.register&&candidate?'/api/register':'/api/login',data);if(r.user.role!==S.authRole){await api('/api/logout',{});throw new Error(`This is a ${r.user.role} account. Select the ${r.user.role} workspace to sign in.`);}S.user=r.user;S.register=false;S.application=null;S.view='dashboard';await refresh();}catch(ex){$('#auth-error').textContent=ex.message;busy(el,false);}};
}

async function refresh(){
  if(S.user?.role==='candidate'){const d=await api('/api/candidate');S.applications=d.applications;}
  else if(S.user){S.pool=await api('/api/recruiter');if(!S.pool.jobs.some(j=>j.id===S.job))S.job=S.pool.jobs[0]?.id;}
  render();
}
function candidateTop(){return `<header class="topbar"><a class="wordmark" href="/candidate">evidence<span>path</span></a><nav class="topnav" aria-label="Candidate navigation"><button data-action="candidate-home" class="${S.tab==='applications'?'active':''}">My applications</button><button data-action="candidate-privacy" class="${S.tab==='privacy'?'active':''}">My data & support</button></nav><div class="row user"><span class="local">On this computer</span><span class="avatar">${initials(S.user.name)}</span><span class="name">${esc(S.user.name)}</span><button class="btn ghost small" data-action="logout">Sign out</button></div></header>`;}
function renderCandidate(){
  let body='';
  if(S.tab==='privacy')body=candidatePrivacy();
  else if(S.application)body=candidateApplication();
  else{
    const applications=S.applications||[],jobs=S.boot.jobs.filter(j=>j.open&&!j.demo);
    body=`<div class="intro"><span class="eyebrow">Your candidate workspace</span><h1>Hello, ${esc(S.user.name.split(' ')[0])}.</h1><p class="muted">Tell the story behind your experience. Show how you approach the work.</p></div>${applications.length?`<section class="stack"><h2>Your applications</h2><div class="position-list">${applications.map(a=>`<article class="card position"><div class="stack" style="gap:9px"><div class="row">${statusTag(a.status)}${a.demo?'<span class="tag gray">Synthetic example</span>':''}</div><h2>${esc(a.job_title)}</h2><p>Last saved ${esc(date(a.updated))}</p>${a.notifications?.length?`<p>${esc(a.notifications.at(-1).text)}</p>`:''}</div>${button(a.status==='draft'?'Continue application':a.status==='invited'?'Open assessment':'View application','open-application',`data-id="${a.id}"`)}</article>`).join('')}</div></section>`:''}<section class="stack"><div class="between"><h2>Open opportunities</h2><span class="small muted">10-minute first stage · about 30 minutes if invited</span></div><div class="position-list">${jobs.map(j=>`<article class="card position"><div><span class="caps">${esc(j.organization)}</span><h2 style="margin-top:7px">${esc(j.title)}</h2><p>${esc(j.description)}</p><div class="coverage-tags">${j.skills.slice(0,5).map(s=>`<span class="tag gray">${esc(s)}</span>`).join('')}</div></div>${button(applications.some(a=>a.job_id===j.id)?'View application':'Start application','start-application',`data-job="${j.id}"`)}</article>`).join('')||'<div class="empty">There are no open campaigns yet.</div>'}</div></section><div class="notice neutral">Paid work is one kind of experience. You can also draw on volunteering, caregiving, community activities and personal projects.</div>`;
  }
  if(!S.application&&S.tab==='applications'&&S.user.username==='demo.candidate')body=`<section class="card stack" style="margin-bottom:24px"><span class="eyebrow">Guided candidate demo</span><h2>Try the whole journey in a few minutes.</h2><p>Explore fictional answers, submit both stages and simulate the recruiter’s invitation and final feedback. No recruiter login is needed.</p>${button('Open guided demo','demo-start')}</section>`+body;
  $('#root').innerHTML=candidateTop()+`<main id="main" class="candidate-main">${body}</main>`;
  bindDraftInputs();bindUploadInputs();bindVideo();
}
function candidatePrivacy(){return `<div class="intro"><span class="eyebrow">Your evidence, explained</span><h1>Your data & support</h1><p class="muted">Access your records, ask for a correction or request help.</p></div><div class="grid2"><section class="card stack"><h2>What stays on this computer</h2><p class="muted">Your application, attachments, assessment responses and reviewer actions are stored in a local database. The recruiter on this computer can access applications in this prototype.</p><p class="small">Passwords are hashed. Application records and attachments are not encrypted at rest. This is a local demonstration, not a production hiring service.</p><a class="btn secondary" href="/api/export.json?workspace=${S.user.role}" download>Export my application records</a></section><section class="card stack"><h2>Assistance and assessment</h2><p class="muted">AI assistance is permitted when disclosed. Reports distinguish your account of an experience from the response you submit to a task.</p><p class="small">The app does not diagnose personality, infer honesty from typing or grade appearance or emotion. Optional work-preference reflection is unscored.</p></section></div><section class="card stack"><h2>Ask for a correction, accommodation or deletion</h2><p class="muted">Choose an application below to record a request for the local recruiter. It appears in that application's activity trail. This does not send an email or automatically delete the original record.</p>${(S.applications||[]).map(a=>`<div class="between"><span>${esc(a.job_title)}</span>${button('Record a request','correction',`data-id="${a.id}"`,'secondary')}</div>`).join('')||'<p class="small muted">Create an application to record a request.</p>'}</section>`;}
function steps(stage){return stage===1?[['Your experience','Application & documents'],['Decision story','Context & contribution'],['Short demonstration','A common work task'],['Review & submit','Your first-stage evidence']]:[['Follow-up questions','Your contribution & choices'],['Work sample','A practical problem'],['Reflection','Assistance & expression'],['Review & submit','Your second-stage evidence']];}
function demoPanel(a){
  if(!a.guided_demo)return '';
  const text=a.status==='draft'?'Stage 1: use the sample answers on each step, edit anything you like, then review and submit. On the story step you can also try the coach.':a.status==='submitted'?'Application submitted. Simulate the recruiter’s invitation to unlock stage 2 without changing browser tabs.':a.status==='invited'?'Stage 2: explore the follow-ups, work sample and optional reflection. Load the sample answers on each step, then submit. A written motivation example replaces the optional video.':a.status==='assessment_submitted'?'Assessment submitted. Simulate a recruiter review to see published ratings, feedback and an interview outcome.':'Journey complete: explore the feedback and printable report below. The interview outcome and ratings are illustrative simulations.';
  return `<section class="notice neutral stack" style="margin-bottom:24px"><div class="between"><strong>Guided demo · fictional applicant</strong><span class="tag orange">Simulated journey</span></div><p>${text}</p><div class="row">${['draft','invited'].includes(a.status)&&S.step<3?button('Use sample answers for this step','demo-fill','','secondary'):''}${['submitted','assessment_submitted'].includes(a.status)?button(a.status==='submitted'?'Simulate recruiter invitation':'Simulate review & interview outcome','demo-advance'):''}${button('Restart guided demo','demo-restart','','ghost small')}</div><small>Only this demo application supports simulated recruiter actions. Normal applications require a recruiter decision. Sample answers replace the text on the current step.</small></section>`;
}
function candidateApplication(){
  const a=S.application,job=S.boot.jobs.find(j=>j.id===a.job_id)||{},editable=a.status==='draft'||a.status==='invited',stage=a.status==='draft'?1:2;
  const intro=`<div class="between"><div class="intro"><button class="inline-help" data-action="candidate-home">‹ Back to applications</button><h1>${esc(job.title||a.job_title)}</h1><div class="row">${statusTag(a.status)}<span class="small muted">${esc(job.organization||'')}</span></div></div><span class="save-status" id="save-status">Saved ${esc(date(a.updated))}</span></div>`;
  if(!editable)return demoPanel(a)+intro+applicationStatus(a,job);
  const list=steps(stage);S.step=Math.max(0,Math.min(3,S.step));
  return demoPanel(a)+intro+`<div class="application-layout"><nav class="steps" aria-label="Assessment steps">${list.map((s,i)=>`<button class="step ${S.step===i?'active':''} ${S.step>i?'done':''}" data-action="step" data-step="${i}" ${S.step===i?'aria-current="step"':''}><span class="step-number">${S.step>i?'✓':i+1}</span><div>${esc(s[0])}<small>${esc(s[1])}</small></div></button>`).join('')}<div class="small muted" style="padding:12px">${stage===1?'Stage one · about 10 minutes':'Stage two · about 20 minutes'}<br>Save and return at any time.</div></nav><div class="card stack">${stage===1?stageOne(a,job):stageTwo(a,job)}<div class="divider"></div><div class="between">${S.step?button('Previous','step',`data-step="${S.step-1}"`,'secondary'):'<span class="small muted">Your work saves as you go.</span>'}${S.step<3?button('Save & continue','step',`data-step="${S.step+1}"`):button(stage===1?'Submit application':'Submit assessment',stage===1?'submit-application':'submit-assessment')}</div><div class="small muted" id="save-extra"></div></div></div>`;
}
function attachments(a,kind){const list=(a.files||[]).filter(f=>!kind||f.kind===kind);return list.map(f=>`<div class="attachment"><a href="/api/files/${f.id}?workspace=${S.user.role}" ${f.kind==='video'?'target="_blank" rel="noopener"':''}>${esc(f.name)}</a><span>${(f.size/1024/1024).toFixed(2)} MB</span></div>`).join('');}
function uploadBlock(a,kind,label){return `<div class="upload"><strong class="small">${label}</strong><span class="small muted">${kind==='video'?'MP4, WEBM or MOV · up to 50 MB · optional':'PDF, DOCX or TXT · up to 10 MB · optional'}</span><input type="file" data-upload="${kind}" aria-label="${label}" accept="${kind==='video'?'.mp4,.webm,.mov':'.pdf,.docx,.txt'}">${attachments(a,kind)}</div>`;}
function stageOne(a,job){const f=a.fields||{};
  if(S.step===0)return `<div class="section-heading"><span class="eyebrow">01 · Your experience</span><h2>There is more than one way to build capability.</h2><p>Share relevant experience. Documents are optional when you provide equivalent context below.</p></div><div class="notice neutral">${esc(job.requirements||'')}</div>${field('Your relevant experience','experience',f.experience,'Paid work, volunteering, community responsibilities or projects are all welcome. At least 30 characters.')}<label class="field"><span>Skills you would like to connect to that experience</span><input data-field="skills" value="${esc(f.skills||'')}" maxlength="1000" placeholder="For example, coordination, communication, information checking"><small>Optional. Explain the connection in your experience or story.</small></label><div class="grid2">${uploadBlock(a,'resume','Résumé')}${uploadBlock(a,'cover','Existing cover letter')}</div><details><summary class="small">Paste equivalent document text</summary><div class="stack" style="margin-top:15px">${field('Résumé text','resume_text',f.resume_text,'Optional alternative to an upload.')}${field('Cover-letter text','cover_text',f.cover_text,'Optional. A newly polished letter is unnecessary.')}</div></details><label class="check"><input type="checkbox" id="consent" ${a.consent?'checked':''}><span>I understand how this local prototype uses my submitted evidence, and that a recruiter decides invitations. I can request an accommodation or correction.</span></label>`;
  if(S.step===1)return `<div class="section-heading"><span class="eyebrow">02 · Decision story</span><h2>Tell us about a decision you made.</h2><p>Choose a specific moment. What was happening, what did you contribute, and why did you choose that approach?</p></div>${field('Your decision story','story',f.story,'At least 80 characters. An imperfect outcome can still be useful to explain.')}<div class="between"><span class="small muted">Need help making your example specific?</span>${button('Ask the story coach','coach','','secondary')}</div><div id="coach-output" class="coach-output"></div>${field('Tools or people who helped','assistance',f.assistance,'Optional disclosure. Assistance is permitted; describe what you checked or changed.',false,true)}<div class="notice neutral">The coach requests context. It does not verify that an event happened or score your honesty.</div>`;
  if(S.step===2)return `<div class="section-heading"><span class="eyebrow">03 · Short demonstration</span><h2>${esc(S.boot.micro_task.title)}</h2><p>A common short task gives every eligible applicant an opportunity to demonstrate their approach.</p></div><p class="prose">${esc(S.boot.micro_task.context)}</p>${field('Your next action and update','micro_task',f.micro_task,S.boot.micro_task.prompt+' At least 40 characters.')}<div class="notice neutral">There may be several effective approaches. Reviewers consider the facts and the reasoning you provide.</div>`;
  const alignment=a.alignment||{};
  return `<div class="section-heading"><span class="eyebrow">04 · Review</span><h2>Review the evidence you want to share.</h2><p>Submission preserves this version. You can still send a factual correction request afterward.</p></div><section class="stack"><h3>Experience</h3><p class="prose">${esc(f.experience)}</p><h3>Decision story</h3><p class="prose">${esc(f.story)}</p><h3>Short demonstration</h3><p class="prose">${esc(f.micro_task)}</p><h3>Declared assistance</h3><p class="prose">${esc(f.assistance||'Not supplied')}</p>${attachments(a)}</section><div class="notice neutral"><strong>${alignment.score??'—'}% application keyword coverage</strong><br>${esc(alignment.explanation||'This counts role keywords mentioned in supplied text. It is not a suitability score or a probability of selection.')}<div class="coverage-tags">${(alignment.matched||[]).map(x=>`<span class="tag green">${esc(x)}</span>`).join('')}${(alignment.unmentioned||[]).map(x=>`<span class="tag gray">Not mentioned: ${esc(x)}</span>`).join('')}</div></div><p class="small muted">You can proceed even when keyword coverage is low. Your practical response provides additional evidence. No application is automatically rejected by this calculation.</p>`;
}
function stageTwo(a){const f=a.assessment||{};
  if(S.step===0)return `<div class="section-heading"><span class="eyebrow">01 · Follow-up</span><h2>A little more context about your decisions.</h2><p>Your experience and first-stage story stay available for reference.</p></div><details><summary class="small">Read your original decision story</summary><p class="prose" style="margin-top:12px">${esc(a.fields.story)}</p></details>${(a.questions||S.boot.questions).map(q=>field(q.label,q.id,f[q.id],q.prompt+' At least 30 characters.',true)).join('')}`;
  if(S.step===1)return `<div class="section-heading"><span class="eyebrow">02 · Work sample</span><h2>${esc((a.scenario||S.boot.scenario).title)}</h2><p>About 12 minutes. Use the disclosed facts and describe a feasible response.</p></div><p class="prose">${esc((a.scenario||S.boot.scenario).context)}</p><div class="notice neutral"><strong>Available facts</strong><ul>${(a.scenario||S.boot.scenario).facts.map(x=>`<li>${esc(x)}</li>`).join('')}</ul></div>${(a.scenario||S.boot.scenario).fields.map(q=>field(q.label,q.id,f[q.id],q.prompt+(q.id==='plan'?' At least 60 characters.':' At least 30 characters.'),true)).join('')}<div class="small muted">Reviewed task ${esc(a.task_version)} · AI assistance is permitted when disclosed. This prototype does not use a hidden timer to infer honesty.</div>`;
  if(S.step===2)return `<div class="section-heading"><span class="eyebrow">03 · Reflection & expression</span><h2>Add the context you want a reviewer to understand.</h2><p>These reflection and expression options are optional. They are not an authorship or personality test.</p></div>${field('What would you check or improve?','reflection',f.reflection,'Optional reflection on the submitted work.',true,true)}${field('Assistance you used during this assessment','assistance',f.assistance,'Explain what was assisted and what you checked or changed.',true,true)}${field('Your motivation for this opportunity','motivation',f.motivation,'You can write here or add an optional short video. Neither is a truthfulness check.',true,true)}<details><summary class="small">Optional work-preference reflection · unscored</summary><div class="stack" style="margin-top:12px"><p class="small muted">Your self-description is kept separate from observed task performance. These ten items have no diagnostic interpretation or effect on your score.</p>${S.boot.preferences.map((p,i)=>`<label class="pref-item"><span>${esc(p)}</span><select data-pref="${i}"><option value="">Skip</option>${['Strongly disagree','Disagree','Neutral','Agree','Strongly agree'].map((v,j)=>`<option value="${j+1}" ${f.preferences?.[i]===j+1?'selected':''}>${v}</option>`).join('')}</select></label>`).join('')}</div></details>${uploadBlock(a,'video','Optional expression video · target 90 seconds')}<div class="row">${button('Record a short video','record-video','','secondary')}<span id="recording-status" class="small muted"></span></div><video id="recording-preview" class="video-preview" controls hidden></video><div class="small muted">Recording starts only after you allow camera and microphone access. It stops after 90 seconds. The file stays local and receives no appearance or emotion score.</div>`;
  return `<div class="section-heading"><span class="eyebrow">04 · Review</span><h2>Your second-stage evidence.</h2><p>A recruiter will review your responses before making the next decision.</p></div>${[...(a.questions||S.boot.questions),...(a.scenario||S.boot.scenario).fields].map(q=>`<section class="stack" style="gap:7px"><h3>${esc(q.label)}</h3><p class="prose">${esc(f[q.id])}</p></section>`).join('')}<h3>Declared assistance</h3><p class="prose">${esc(f.assistance||'Not supplied')}</p>${attachments(a,'video')}<div class="notice neutral">Submitting freezes this version. Assessment completion does not guarantee an interview. Your recruiter controls invitations and publishes feedback separately.</div>`;
}
function applicationStatus(a,job){const review=a.review||{},scores=review.scores||{};
  return `<div class="grid2"><section class="card stack"><h2>${a.status==='submitted'?'Your first-stage evidence is with the recruiter.':a.status==='assessment_submitted'?'Your assessment is ready for review.':a.status==='interview'?'The recruiter selected you for an interview.':a.status==='withdrawn'?'You withdrew this application.':'The recruiter has closed this application.'}</h2><p class="muted">${a.status==='interview'?'Interview scheduling happens separately with the employer.':a.status==='withdrawn'?'Your saved evidence remains available to you.':'You can return here for updates and published feedback.'}</p><div class="timeline">${(a.notifications||[]).slice().reverse().map(n=>`<div class="timeline-item"><small>${esc(date(n.date))}</small><p>${esc(n.text)}</p>${n.reason?`<p class="small muted">Recruiter note: ${esc(n.reason)}</p>`:''}</div>`).join('')}</div><div class="row"><a class="btn secondary" href="/api/report?id=${a.id}&workspace=${S.user.role}" target="_blank" rel="noopener">Printable evidence report</a>${button('Request a correction','correction',`data-id="${a.id}"`,'secondary')}</div>${!['withdrawn','not_proceeding'].includes(a.status)?button('Withdraw application','withdraw',`data-id="${a.id}"`,'ghost'):''}</section><section class="card stack"><h2>Published reviewer feedback</h2>${review.published?`<p class="prose">${esc(review.feedback)}</p>${S.boot.criteria.map(c=>`<div class="score-line"><span>${esc(c.name)}</span><div class="score-track"><div class="score-fill" style="width:${(scores[c.id]||0)*25}%"></div></div><span>${scores[c.id]??'—'} / 4</span></div>`).join('')}<p class="small muted">These are human-entered findings for this task, not a validated prediction of job success.</p>`:'<p class="muted">The recruiter has not published feedback yet. Missing feedback is not a negative score.</p>'}</section></div><section class="card stack"><h2>Your submitted evidence</h2><details><summary>Experience and decision story</summary><div class="stack" style="margin-top:16px"><p class="prose">${esc(a.fields.experience)}</p><p class="prose">${esc(a.fields.story)}</p><h3>Short demonstration</h3><p class="prose">${esc(a.fields.micro_task)}</p></div></details>${a.assessment?.plan?`<details><summary>Second-stage responses</summary><div class="stack" style="margin-top:16px">${[...(a.questions||S.boot.questions),...(a.scenario||S.boot.scenario).fields].map(q=>`<section><h3>${esc(q.label)}</h3><p class="prose">${esc(a.assessment[q.id])}</p></section>`).join('')}</div></details>`:''}${attachments(a)}</section>`;
}

function bindDraftInputs(){
  for(const el of $$('[data-field],[data-answer],[data-pref],#consent'))el.addEventListener('input',()=>{const status=$('#save-status');if(status)status.textContent='Unsaved changes';clearTimeout(saveTimer);saveTimer=setTimeout(()=>saveDraft().catch(ex=>toast(ex.message,true)),800);});
}
function saveDraft(){
  const a=S.application;if(!a||!['draft','invited'].includes(a.status)||!S.user||S.user.role!=='candidate')return saveChain;
  const sid=a.id,stage=a.status;
  const fields=Object.fromEntries($$('[data-field]').map(el=>[el.dataset.field,el.value]));
  const answers=Object.fromEntries($$('[data-answer]').map(el=>[el.dataset.answer,el.value]));
  const pref=$$('[data-pref]');if(pref.length)answers.preferences=Object.fromEntries(pref.filter(el=>el.value).map(el=>[el.dataset.pref,Number(el.value)]));
  const consent=$('#consent')?.checked??a.consent;
  if(stage==='draft'&&!Object.keys(fields).length)return saveChain;
  if(stage==='invited'&&!Object.keys(answers).length)return saveChain;
  const task=async()=>{if(!S.application||S.application.id!==sid)return;const status=$('#save-status');if(status)status.textContent='Saving…';const data=stage==='draft'?{id:sid,revision:S.application.revision,fields,consent}:{id:sid,revision:S.application.revision,assessment:answers};const result=await api(stage==='draft'?'/api/candidate/save':'/api/candidate/assessment-save',data);if(S.application?.id===sid)S.application=result.application;const label=$('#save-status');if(label)label.textContent='All changes saved';};
  saveChain=saveChain.catch(()=>{}).then(task);return saveChain;
}
async function flush(){clearTimeout(saveTimer);saveTimer=null;await saveDraft();}
function bindUploadInputs(){for(const input of $$('[data-upload]'))input.onchange=async()=>{const file=input.files[0];if(!file)return;try{await flush();await upload(file,input.dataset.upload);renderCandidate();toast('Attachment saved on this computer.');}catch(ex){toast(ex.message,true);}finally{input.value='';}};}
async function upload(file,kind,sid=S.application?.id){
  const max=kind==='video'?50:10;if(file.size>max*1024*1024)throw new Error(`Choose a file smaller than ${max} MB.`);
  const response=await fetch('/api/upload',{method:'POST',credentials:'same-origin',headers:{'Content-Type':file.type||'application/octet-stream','X-Evidence-Path':'1','X-Workspace':'candidate','X-Application-Id':sid,'X-File-Kind':kind,'X-File-Name':encodeURIComponent(file.name)},body:file});
  const data=await response.json();if(!response.ok)throw new Error(data.error||'Upload failed.');if(S.application?.id===sid)S.application=data.application;if(data.notice&&!data.notice.startsWith('Saved'))toast(data.notice);return data;
}
function bindVideo(){const files=S.application?.files?.filter(f=>f.kind==='video')||[];const v=$('#recording-preview');if(v&&files.length){v.src='/api/files/'+files.at(-1).id+'?workspace=candidate';v.hidden=false;}}

function recruiterShell(body){const job=S.pool?.jobs.find(j=>j.id===S.job);return `<div class="workspace"><aside class="sidebar"><a href="/recruiter" class="wordmark">evidence<span>path</span></a><div><div class="section-label">Recruiter workspace</div><nav aria-label="Recruiter navigation">${[['dashboard','◈','Overview'],['pool','≡','Candidate pool'],['campaigns','▤','Campaigns'],['settings','⚙','Local AI & access'],['audit','◷','Activity log']].map(([id,icon,label])=>`<button class="nav-item ${S.view===id?'active':''}" data-action="recruiter-nav" data-view="${id}"><span class="nav-icon" aria-hidden="true">${icon}</span>${label}</button>`).join('')}</nav></div><div class="sidebar-bottom"><span class="local">On this computer</span><p>Local prototype. Scores support review and never trigger an automatic outcome.</p><div class="row"><span class="avatar">${initials(S.user.name)}</span><span class="small">${esc(S.user.name)}</span></div>${button('Sign out','logout','','ghost')}</div></aside><div class="recruiter-body"><header class="recruiter-header"><div class="row"><span class="caps">Campaign</span><select id="campaign-select" aria-label="Select campaign">${(S.pool?.jobs||[]).map(j=>`<option value="${j.id}" ${j.id===S.job?'selected':''}>${esc(j.title)}</option>`).join('')}</select>${job?.demo?'<span class="tag gray">Synthetic pool</span>':''}</div><div class="row"><span class="small muted">Human decisions · linked evidence</span>${button('Refresh','recruiter-refresh','','secondary small')}</div></header><main id="main" class="recruiter-content">${body}</main></div></div>`;}
function poolApplications(){return (S.pool?.applications||[]).filter(a=>a.job_id===S.job);}
function renderRecruiter(){
  if(!S.pool){loading();return;}
  let body='';if(S.view==='detail')body=recruiterDetail();else if(S.view==='settings')body=settingsPage();else if(S.view==='campaigns')body=campaignsPage();else if(S.view==='audit')body=auditPage();else if(S.view==='pool')body=poolPage();else body=dashboard();
  $('#root').innerHTML=recruiterShell(body);
  const select=$('#campaign-select');if(select)select.onchange=()=>{S.job=select.value;S.application=null;if(S.view==='detail')S.view='pool';renderRecruiter();};
  if(['dashboard','pool'].includes(S.view))bindPool();if(S.view==='dashboard')requestAnimationFrame(drawMap);
  if(S.view==='campaigns')bindCampaign();if(S.view==='detail')bindReview();if(S.view==='settings')bindSettings();
}
function dashboard(){const list=poolApplications(),count=status=>list.filter(a=>a.status===status).length,reviewed=list.filter(a=>a.review?.overall!=null),active=list.filter(a=>!['draft','withdrawn'].includes(a.status)).length;
  return `<div class="between"><div class="intro"><span class="eyebrow">Your hiring overview</span><h1>Evidence before assumptions.</h1><p class="muted">See who is in the pool, what has been reviewed and what needs your attention.</p></div><a class="btn secondary" href="/api/export.csv?job=${S.job}&workspace=recruiter" download>Export pool</a></div><div class="stats"><section class="card metric"><p>Submitted candidates</p><div class="value">${active}</div><small class="muted">${list.length} records in this campaign</small></section><section class="card metric"><p>Awaiting first review</p><div class="value">${count('submitted')}</div><small class="muted">Ready for a human decision</small></section><section class="card metric"><p>Assessment received</p><div class="value">${count('assessment_submitted')}</div><small class="muted">Second-stage evidence available</small></section><section class="card metric"><p>Interview selected</p><div class="value">${count('interview')}</div><small class="muted">Chosen by a recruiter</small></section></div><div class="dashboard-split"><section class="card chart-card stack"><div class="between"><div><h2>Reviewed evidence map</h2><p class="small muted">Human criterion scores · each axis 0–100</p></div><span class="tag gray">${reviewed.length} reviewed</span></div><div id="evidence-map" class="plot" role="img" aria-label="Three-dimensional map of human-reviewed reasoning, communication and prioritization scores"></div><div class="chart-legend">${colors.map((c,i)=>`<span><i class="legend-color" style="background:${c}"></i>Rank group ${i+1}</span>`).join('')}</div><div class="between"><label class="small row">View angle <input id="map-rotation" type="range" min="15" max="75" value="${S.rotation}" aria-label="Map rotation"></label><span class="small muted">Drag to rotate · click a point to review</span></div><p class="plot-note">Group 1 has the highest complete weighted review scores in this campaign. Ties stay together. Missing evidence stays unranked.</p></section><section class="card stack"><div><h2>Pipeline</h2><p class="small muted">Every status remains visible.</p></div><div>${['submitted','invited','assessment_submitted','interview','not_proceeding','withdrawn'].map(status=>`<div class="stage-row"><span>${esc(S.boot.statuses[status])}</span><div class="stage-bar"><span style="width:${list.length?count(status)/list.length*100:0}%"></span></div><strong>${count(status)}</strong></div>`).join('')}</div><div class="divider"></div><h3>What this map shows</h3><p class="small muted">It summarizes human-entered findings from disclosed tasks. It does not measure authenticity, personality or probability of job success.</p>${button('Explore all candidates','recruiter-nav','data-view="pool"','secondary')}</section></div>${poolTable(list.slice(0,8),'Recent candidates',false)}`;
}
function poolPage(){return `<div class="between"><div class="intro"><span class="eyebrow">Candidate pool</span><h1>Every application, in view.</h1><p class="muted">Compare the findings, then open the evidence behind them.</p></div><div class="row"><a class="btn secondary" href="/api/export.csv?job=${S.job}&workspace=recruiter" download>Export CSV</a><a class="btn secondary" href="/api/export.json?job=${S.job}&workspace=recruiter" download>Evidence JSON</a></div></div><div class="toolbar"><input id="candidate-search" class="search" aria-label="Search candidates" placeholder="Search candidate name…" value="${esc(S.search)}"><select id="status-filter" aria-label="Filter candidate status"><option value="all">All statuses</option>${Object.entries(S.boot.statuses).map(([k,v])=>`<option value="${k}" ${S.filter===k?'selected':''}>${esc(v)}</option>`).join('')}</select><select id="pool-sort" aria-label="Sort candidates"><option value="score" ${S.sort==='score'?'selected':''}>Review score</option><option value="recent" ${S.sort==='recent'?'selected':''}>Most recent</option><option value="name" ${S.sort==='name'?'selected':''}>Name</option></select></div>${poolTable(filteredPool(),'Candidate evidence',true)}<div class="notice neutral">Keyword coverage describes the words mentioned in an application. Human review scores describe task evidence. The two measures stay separate.</div>`;}
function filteredPool(){return poolApplications().filter(a=>(S.filter==='all'||a.status===S.filter)&&a.name.toLowerCase().includes(S.search.toLowerCase())).sort((a,b)=>S.sort==='name'?a.name.localeCompare(b.name):S.sort==='recent'?b.updated.localeCompare(a.updated):(b.review?.overall??-1)-(a.review?.overall??-1)||a.name.localeCompare(b.name));}
function poolTable(list,title,filtered){return `<section class="card table-card"><div class="between"><h2>${esc(title)}</h2><span id="pool-count" class="small muted">${list.length} ${filtered?'matching records':'shown'}</span></div><div class="table-wrap"><table><thead><tr><th>Candidate</th><th>Status</th><th>Review /100</th><th>Pool rank</th><th>Word coverage</th><th>Evidence</th></tr></thead><tbody id="candidate-rows">${candidateRows(list)}</tbody></table></div>${!list.length?'<div class="empty"><h2>No matching candidates yet.</h2><p>New submissions appear here automatically.</p></div>':''}</section>`;}
function candidateRows(list){return list.map(a=>`<tr data-id="${a.id}"><td><div class="candidate-cell"><span class="avatar">${initials(a.name)}</span><div>${esc(a.name)}${a.demo?'<small>Synthetic example</small>':`<small>Updated ${esc(date(a.updated))}</small>`}</div></div></td><td>${statusTag(a.status)}</td><td>${a.review?.overall!=null?`<strong>${a.review.overall.toFixed(1)}</strong>`:'<span class="muted">Not complete</span>'}</td><td>${a.rank?`#${a.rank} <span class="small muted">· group ${a.tier}</span>`:'<span class="muted">Unranked</span>'}</td><td><span class="muted">${a.alignment?.score??'—'}%</span></td><td><button data-action="review-candidate" data-id="${a.id}">Review <span aria-hidden="true">↗</span></button></td></tr>`).join('');}
function bindPool(){const update=()=>{const list=filteredPool();$('#candidate-rows').innerHTML=candidateRows(list);$('#pool-count').textContent=list.length+' matching records';};const search=$('#candidate-search');if(search)search.oninput=()=>{S.search=search.value;update();};const filter=$('#status-filter');if(filter)filter.onchange=()=>{S.filter=filter.value;update();};const sort=$('#pool-sort');if(sort)sort.onchange=()=>{S.sort=sort.value;update();};const slider=$('#map-rotation');if(slider)slider.oninput=()=>{S.rotation=Number(slider.value);drawMap();};}

function drawMap(){const root=$('#evidence-map');if(!root)return;const data=poolApplications().filter(a=>a.review?.overall!=null&&a.rank),w=Math.max(270,root.clientWidth),h=w<420?330:360;
  if(!data.length){root.innerHTML='<div class="empty"><h2>The map is ready for evidence.</h2><p>Complete all four human criterion ratings to place an applicant here.</p></div>';return;}
  const angle=S.rotation*Math.PI/180,e=28*Math.PI/180,raw=v=>[Math.cos(angle)*v[0]-Math.sin(angle)*v[1],-Math.sin(e)*(Math.sin(angle)*v[0]+Math.cos(angle)*v[1])-Math.cos(e)*v[2]],corners=[0,100].flatMap(x=>[0,100].flatMap(y=>[0,100].map(z=>raw([x,y,z])))),xs=corners.map(v=>v[0]),ys=corners.map(v=>v[1]),minX=Math.min(...xs),maxX=Math.max(...xs),minY=Math.min(...ys),maxY=Math.max(...ys),scale=Math.min((w-85)/(maxX-minX),(h-80)/(maxY-minY)),p=v=>{const q=raw(v);return [w/2+scale*(q[0]-(minX+maxX)/2),h/2-4+scale*(q[1]-(minY+maxY)/2)];};
  const marks=[],line=(v,u,color='#d8e1e7',width=1)=>{const a=p(v),b=p(u);marks.push(`<line x1="${a[0]}" y1="${a[1]}" x2="${b[0]}" y2="${b[1]}" stroke="${color}" stroke-width="${width}"/>`);},text=(v,value,dx=0,dy=0,anchor='middle')=>{const q=p(v);marks.push(`<text x="${q[0]+dx}" y="${q[1]+dy}" fill="#607580" font-size="10" text-anchor="${anchor}">${value}</text>`);};
  for(const t of [0,50,100]){line([t,0,0],[t,100,0]);line([0,t,0],[100,t,0]);line([0,100,t],[100,100,t]);}
  line([0,0,0],[100,0,0],'#728795');line([0,0,0],[0,100,0],'#728795');line([0,100,0],[0,100,100],'#728795');
  for(const t of [0,50,100]){text([t,0,0],t,5,15);if(t)text([0,t,0],t,-5,15);text([0,100,t],t,-8,3,'end');}
  text([65,0,0],'Reasoning',9,35);text([0,65,0],'Communication',-5,35);text([0,100,100],'Prioritization',12,-14);
  const points=data.map(a=>{const s=a.review.scores,v=[s.reasoning*25,s.communication*25,s.prioritization*25];return {a,v,depth:Math.sin(angle)*v[0]+Math.cos(angle)*v[1]};}).sort((a,b)=>b.depth-a.depth);
  for(const {a,v} of points){const q=p(v),color=colors[a.tier-1]||colors[4];marks.push(`<circle data-point-id="${a.id}" cx="${q[0]}" cy="${q[1]}" r="4.6" fill="${color}" opacity=".85"><title>${esc(a.name)} · ${a.review.overall}/100 · pool rank ${a.rank}</title></circle>`);}
  root.innerHTML=`<svg xmlns="http://www.w3.org/2000/svg" width="${w}" height="${h}" viewBox="0 0 ${w} ${h}" aria-hidden="true">${marks.join('')}</svg>`;
  if(!root.dataset.bound){root.dataset.bound='1';let drag=null;root.onpointerdown=ev=>{if(ev.button!==0)return;drag={x:ev.clientX,angle:S.rotation,moved:false,point:ev.target.dataset.pointId};root.setPointerCapture(ev.pointerId);};root.onpointermove=ev=>{if(!drag)return;if(Math.abs(ev.clientX-drag.x)>5){drag.moved=true;S.rotation=Math.max(15,Math.min(75,drag.angle+(ev.clientX-drag.x)*.2));const slider=$('#map-rotation');if(slider)slider.value=S.rotation;drawMap();}};root.onpointerup=ev=>{if(drag&&!drag.moved&&drag.point)openReview(drag.point).catch(ex=>toast(ex.message,true));drag=null;};root.onpointercancel=()=>drag=null;}
}

function recruiterDetail(){const a=S.application;if(!a)return '<p>Opening evidence…</p>';const review=a.review||{},f=a.fields||{},answers=a.assessment||{};let evidence='';
  if(S.reviewTab==='activity')evidence=`<section class="card stack"><h2>Application activity</h2><div class="audit-list">${(a.events||[]).slice().reverse().map(event=>`<article class="audit-row"><div class="between"><strong>${esc(event.kind.replaceAll('_',' '))}</strong><span class="small muted">${esc(date(event.created))}</span></div><pre>${esc(JSON.stringify(event.detail,null,2))}</pre></article>`).join('')||'<p class="muted">No recorded events for this synthetic profile.</p>'}</div></section>`;
  else if(S.reviewTab==='assessment')evidence=`<section class="card stack"><h2>Second-stage evidence</h2>${answers.plan?`${[...(a.questions||S.boot.questions),...(a.scenario||S.boot.scenario).fields].map(q=>`<section class="question"><h3>${esc(q.label)}</h3><p class="prose">${esc(answers[q.id])}</p></section>`).join('')}<h3>Reflection and motivation</h3><p class="prose">${esc([answers.reflection,answers.motivation].filter(Boolean).join('\n\n'))}</p><h3>Declared assessment assistance</h3><p class="prose">${esc(answers.assistance||'Not supplied')}</p>${attachments(a,'video')}${a.files?.some(f=>f.kind==='video')?`<video class="video-preview" controls src="/api/files/${a.files.filter(f=>f.kind==='video').at(-1).id}?workspace=recruiter"></video><p class="small muted">Optional expression. No appearance, accent or emotion score.</p>`:''}<details><summary class="small">Unscored work-preference self-report</summary><div class="stack" style="margin-top:15px">${Object.entries(answers.preferences||{}).map(([k,v])=>`<p class="small">${esc(S.boot.preferences[Number(k)])} <strong>${v}/5</strong></p>`).join('')||'<p class="small muted">Skipped.</p>'}</div></details>`:'<p class="muted">No second-stage response has been submitted. An invitation unlocks the candidate assessment.</p>'}</section>`;
  else evidence=`<section class="card stack"><h2>Application evidence</h2><section><h3>Relevant experience</h3><p class="prose">${esc(f.experience)}</p></section><section><h3>Skills linked by the candidate</h3><p class="prose">${esc(f.skills)}</p></section><section><h3>Decision story</h3><p class="prose">${esc(f.story)}</p></section><section><h3>Common short demonstration</h3><p class="prose">${esc(f.micro_task)}</p></section><section><h3>Declared assistance</h3><p class="prose">${esc(f.assistance||'Not supplied')}</p></section>${attachments(a).replaceAll('target="_blank"','target="_blank"')}<details><summary class="small">Document text and extraction</summary><div class="stack" style="margin-top:15px">${fieldRead('Pasted résumé',f.resume_text)}${fieldRead('Pasted cover letter',f.cover_text)}${(a.files||[]).filter(f=>f.kind!=='video').map(f=>fieldRead(f.name,f.extracted_text||'No extracted text. Download the original for review.')).join('')}</div></details><div class="notice neutral"><strong>${a.alignment?.score??'—'}% keyword coverage</strong><br>Word mentions only. Missing keywords do not establish missing capability.</div></section>`;
  const closed=['draft','withdrawn','not_proceeding'].includes(a.status);
  return `<div class="between"><div class="intro"><button class="inline-help" data-action="recruiter-nav" data-view="pool">‹ Back to candidate pool</button><h1>${esc(a.name)}</h1><div class="row">${statusTag(a.status)}${a.demo?'<span class="tag gray">Synthetic candidate</span>':''}<span class="small muted">${esc(a.job_title)}</span></div></div><a class="btn secondary" href="/api/report?id=${a.id}&workspace=${S.user.role}" target="_blank" rel="noopener">Printable report</a></div><div class="review-layout"><div class="stack"><nav class="section-tabs" aria-label="Evidence sections">${[['evidence','Application'],['assessment','Assessment'],['activity','Activity & requests']].map(([id,label])=>`<button class="${S.reviewTab===id?'active':''}" data-action="review-tab" data-tab="${id}">${label}</button>`).join('')}</nav>${evidence}</div><aside class="stack"><section class="card stack"><div><h2>Human evidence review</h2><p class="small muted">Use the criterion anchors. Leave unobserved areas blank.</p></div><form id="review-form" class="stack">${S.boot.criteria.map(c=>`<div class="review-field"><label for="score-${c.id}">${esc(c.name)}<small>${esc(c.description)}</small></label><select id="score-${c.id}" name="${c.id}" ${closed?'disabled':''}><option value="">Not observed</option>${[1,1.5,2,2.5,3,3.5,4].map(v=>`<option value="${v}" ${Number(review.scores?.[c.id])===v?'selected':''}>${v} / 4</option>`).join('')}</select></div>`).join('')}<details><summary class="small">Review score anchors</summary><ul class="small muted">${S.boot.anchors.map(x=>`<li>${esc(x)}</li>`).join('')}</ul><p class="small muted">An overall comparison requires all four criteria. It is a task finding, not a probability of success.</p></details><label class="field"><span>Evidence and rationale</span><textarea name="rationale" class="short" ${closed?'disabled':''}>${esc(review.rationale||'')}</textarea><small>Quote or identify the response that supports your interpretation. At least 20 characters.</small></label><label class="field"><span>Candidate feedback</span><textarea name="feedback" class="short" ${closed?'disabled':''}>${esc(review.feedback||'')}</textarea></label><label class="check"><input name="published" type="checkbox" ${review.published?'checked':''} ${closed?'disabled':''}><span>Publish criterion ratings and feedback to this candidate.</span></label><button class="btn primary" type="submit" ${closed?'disabled':''}>Save reviewer findings</button></form></section><section class="card stack"><h2>Recruiter decision</h2><p class="small muted">Each action requires a reason and appears in the local candidate workspace. No external messages are sent.</p>${a.status==='submitted'?button('Invite to assessment','recruiter-action','data-value="invite"'):a.status==='assessment_submitted'?button('Select for interview','recruiter-action','data-value="interview"'):''}${!closed?button('Do not proceed','recruiter-action','data-value="decline"','danger'):'<p class="muted small">This application is closed or not submitted.</p>'}</section></aside></div>`;
}
function fieldRead(label,value){return `<section><h3>${esc(label)}</h3><p class="prose">${esc(value||'Not supplied')}</p></section>`;}
function bindReview(){const form=$('#review-form');if(form)form.onsubmit=async ev=>{ev.preventDefault();const btn=$('button[type=submit]',form);busy(btn,true);try{const raw=Object.fromEntries(new FormData(form));const scores=Object.fromEntries(S.boot.criteria.map(c=>[c.id,raw[c.id]?Number(raw[c.id]):null]));const result=await api('/api/recruiter/review',{id:S.application.id,scores,rationale:raw.rationale,feedback:raw.feedback,published:raw.published==='on'});S.application={...S.application,...result.application};toast('Reviewer findings saved'+(raw.published?' and published.':'.'));S.pool=await api('/api/recruiter');}catch(ex){toast(ex.message,true);}finally{busy(btn,false);}};}

function campaignsPage(){return `<div class="intro"><span class="eyebrow">Campaign design</span><h1>The criteria come first.</h1><p class="muted">Define a role and weights before reviewing applicants. Submitted campaigns keep their original criteria.</p></div><div class="grid2"><section class="card stack"><h2>Create a campaign</h2><form id="campaign-form" class="stack"><label class="field"><span>Position title</span><input name="title" required maxlength="160"></label><label class="field"><span>Employer display name</span><input name="organization" required maxlength="160"></label><label class="field"><span>Opportunity description</span><textarea name="description" class="short" required></textarea></label><label class="field"><span>Essential requirements</span><textarea name="requirements" class="short" required></textarea></label><label class="field"><span>Role keywords, separated by commas</span><input name="skills" required placeholder="coordination, communication, planning"></label><h3>Criterion weights</h3>${S.boot.criteria.map(c=>`<label class="criteria-weight small"><span>${esc(c.name)}</span><input name="weight-${c.id}" type="number" min="0" max="100" value="25" required aria-label="${esc(c.name)} weight percent"></label>`).join('')}<p class="small muted">Weights must total 100%. No candidate is automatically rejected by a score.</p><button class="btn primary" type="submit">Create local campaign</button></form></section><section class="stack"><h2>Existing campaigns</h2><div class="campaign-list">${S.pool.jobs.map(j=>`<article class="card stack"><div class="row"><h3>${esc(j.title)}</h3>${j.demo?'<span class="tag gray">Synthetic</span>':''}</div><p class="muted">${esc(j.organization)}</p><p>${esc(j.description)}</p><div class="small muted">${S.boot.criteria.map(c=>`${esc(c.name)} ${j.weights[c.id]}%`).join(' · ')}</div>${button('Open candidate pool','select-job',`data-job="${j.id}"`,'secondary')}</article>`).join('')}</div></section></div>`;}
function bindCampaign(){const form=$('#campaign-form');if(form)form.onsubmit=async ev=>{ev.preventDefault();const b=$('button[type=submit]',form);busy(b,true);try{const raw=Object.fromEntries(new FormData(form));const weights=Object.fromEntries(S.boot.criteria.map(c=>[c.id,Number(raw['weight-'+c.id])]));const r=await api('/api/recruiter/job',{...raw,weights,skills:raw.skills.split(',').map(s=>s.trim()).filter(Boolean)});S.job=r.job.id;S.view='pool';S.boot=await api('/api/bootstrap');S.pool=await api('/api/recruiter');renderRecruiter();toast('Campaign created. It is available in the candidate workspace.');}catch(ex){toast(ex.message,true);busy(b,false);}};}
function settingsPage(){const a=S.ai;return `<div class="intro"><span class="eyebrow">Local operation</span><h1>Your workspace, your computer.</h1><p class="muted">The app works offline. A local model is optional and stays separate from human scoring.</p></div><div class="grid2"><section class="card stack"><div class="between"><h2>Story-coach assistance</h2><span class="tag ${a?.available?'green':'gray'}">${a?.available?'Local model service found':'Offline guidance'}</span></div><p class="muted">Without a model, the coach uses disclosed, structured guidance. It does not pretend to be a generative AI service.</p>${a?`<form id="ai-form" class="stack"><label class="check"><input name="enabled" type="checkbox" ${a.settings.enabled?'checked':''} ${!a.available?'disabled':''}><span>Enable an installed Ollama model for story-coach questions.</span></label><label class="field"><span>Installed local model</span><select name="model"><option value="">Select a model</option>${a.models.map(m=>`<option value="${esc(m)}" ${m===a.settings.model?'selected':''}>${esc(m)}</option>`).join('')}</select></label><p class="small muted">The backend connects only to 127.0.0.1:11434. Candidate text is sent to that local service when coaching is requested. Model output cannot change scores or recruiter decisions.</p><button class="btn primary" type="submit">Save AI settings</button></form>`:'<p class="muted">Checking local model availability…</p>'}${button('Check local service','check-ai','','secondary')}</section><section class="card stack"><h2>Access and storage</h2><p class="muted">Candidate and recruiter accounts share a local SQLite database. Session cookies restrict access between workspaces.</p><p class="small">Recruiter credentials are generated at first launch and saved in <strong>data/.local-access.txt</strong>. Candidate passwords are hashed. The server binds only to the loopback interface.</p><div class="notice neutral">Records and attachments are not encrypted at rest. Access to this machine's files can expose them. This build is for local demonstrations, not deployment with real applicants.</div><h3>Data handling</h3><p class="small muted">There is no automatic retention deletion. Candidate correction and deletion requests appear in the activity log for manual handling. Export records before any deliberate data cleanup.</p><a class="btn secondary" href="/api/export.json?workspace=${S.user.role}" download>Export local application records</a><div class="divider"></div><h3>Stop this local instance</h3><p class="small muted">Saved records stay on disk. Use the launcher to start again.</p>${button('Stop local server','stop-server','','danger')}</section></div>`;}
function bindSettings(){const form=$('#ai-form');if(form)form.onsubmit=async ev=>{ev.preventDefault();try{const raw=new FormData(form);await api('/api/recruiter/ai',{enabled:raw.get('enabled')==='on',model:raw.get('model')});S.ai=await api('/api/recruiter/ai');renderRecruiter();toast('Local AI preference saved.');}catch(ex){toast(ex.message,true);}};}
function auditPage(){return `<div class="between"><div class="intro"><span class="eyebrow">Recorded actions</span><h1>An inspectable activity trail.</h1><p class="muted">Submissions, recruiter decisions, revisions and candidate requests stay traceable.</p></div>${button('Refresh activity','load-audit','','secondary')}</div><section class="card audit-list">${(S.events||[]).map(ev=>`<article class="audit-row"><div class="between"><strong>${esc(ev.kind.replaceAll('_',' '))}</strong><span class="small muted">${esc(date(ev.created))}</span></div><pre>${esc(JSON.stringify(ev.detail,null,2))}</pre>${ev.application_id?button('Open application','review-candidate',`data-id="${ev.application_id}"`,'ghost small'):''}</article>`).join('')||'<div class="empty"><h2>No activity to show yet.</h2><p>New application and reviewer events will appear here.</p></div>'}</section>`;}

async function openDemo(action='start'){await flush();const r=await api('/api/candidate/demo',{action});S.boot=await api('/api/bootstrap');S.application=r.application;S.step=0;S.tab='applications';renderCandidate();window.scrollTo(0,0);}
async function openApplication(id){await flush();const result=await api('/api/application/'+id);S.application=result.application;S.step=0;S.tab='applications';renderCandidate();window.scrollTo(0,0);}
async function openReview(id){const result=await api('/api/application/'+id);S.application=result.application;S.view='detail';S.reviewTab='evidence';renderRecruiter();window.scrollTo(0,0);}
function requestDialog(title,description,label,handler,minLength=10){const d=$('#dialog');$('#dialog-content').innerHTML=`<form id="dialog-form" class="stack"><div class="stack" style="gap:8px"><h2>${esc(title)}</h2><p class="muted small">${esc(description)}</p></div><label class="field"><span>${esc(label)}</span><textarea name="message" minlength="${minLength}" maxlength="4000" required></textarea></label><div class="row">${button('Cancel','close-dialog','','secondary')}<button class="btn primary" type="submit">Confirm</button></div><p id="dialog-error" class="small" role="alert"></p></form>`;d.showModal();$('#dialog-form').onsubmit=async ev=>{ev.preventDefault();const button=$('button[type=submit]',ev.target);busy(button,true);try{await handler(new FormData(ev.target).get('message'));d.close();}catch(ex){$('#dialog-error').textContent=ex.message;$('#dialog-error').style.color='var(--danger)';busy(button,false);}};}

document.addEventListener('click',async event=>{
  const control=event.target.closest('[data-action]');
  if(!control){const row=event.target.closest('tr[data-id]');if(row&&S.user?.role==='recruiter')openReview(row.dataset.id).catch(ex=>toast(ex.message,true));return;}
  const action=control.dataset.action;
  try{
    if(action==='auth-role'){S.authRole=control.dataset.value;S.register=false;history.replaceState(null,'','/'+S.authRole);auth();}
    else if(action==='auth-toggle'){S.register=!S.register;auth();}
    else if(action==='demo-login'){const r=await api('/api/login',{username:'demo.candidate',password:'candidate-demo'});S.user=r.user;S.tab='applications';await openDemo();}
    else if(action==='demo-start')await openDemo();
    else if(action==='demo-fill'||action==='demo-advance'){busy(control,true);await flush();const r=await api('/api/candidate/demo',{action:action==='demo-fill'?'fill':'advance',step:S.step,revision:S.application.revision});S.application=r.application;if(action==='demo-advance')S.step=0;renderCandidate();toast(action==='demo-fill'?'Fictional sample answers loaded. You can edit them.':'Simulated recruiter response recorded.');window.scrollTo(0,0);}
    else if(action==='demo-restart')requestDialog('Restart guided demo','This resets the fictional demo answers, submissions and outcome. Other applications are preserved.','Type RESTART to confirm',async message=>{if(message.trim()!=='RESTART')throw new Error('Type RESTART to reset this demo.');await openDemo('restart');},7);
    else if(action==='logout'){await flush();await api('/api/logout',{});S.user=null;S.application=null;S.pool=null;S.authRole=location.pathname==='/recruiter'?'recruiter':'candidate';render();}
    else if(action==='candidate-home'){await flush();S.application=null;S.tab='applications';S.boot=await api('/api/bootstrap');await refresh();}
    else if(action==='candidate-privacy'){await flush();S.application=null;S.tab='privacy';await refresh();}
    else if(action==='start-application'){const r=await api('/api/candidate/start',{job_id:control.dataset.job});S.application=r.application;S.step=0;renderCandidate();window.scrollTo(0,0);}
    else if(action==='open-application')await openApplication(control.dataset.id);
    else if(action==='step'){await flush();if(recorder?.state==='recording')throw new Error('Stop the recording before moving to another step.');S.step=Number(control.dataset.step);renderCandidate();window.scrollTo({top:0,behavior:'instant'});}
    else if(action==='coach'){busy(control,true);await flush();const answer=await api('/api/candidate/coach',{id:S.application.id});$('#coach-output').innerHTML=`<div class="notice"><strong>${esc(answer.mode)}</strong>${answer.model?` · ${esc(answer.model)}`:''}<ul>${answer.suggestions.map(s=>`<li>${esc(s)}</li>`).join('')}</ul>${answer.local_ai?`<div class="divider" style="margin:16px 0"></div><p class="prose">${esc(answer.local_ai)}</p>`:''}${answer.notice?`<p class="small">${esc(answer.notice)}</p>`:''}</div>`;busy(control,false);}
    else if(action==='submit-application'||action==='submit-assessment'){busy(control,true);await flush();const r=await api(action==='submit-application'?'/api/candidate/submit':'/api/candidate/assessment-submit',{id:S.application.id});S.application=r.application;renderCandidate();toast('Evidence submitted. You can return here for updates.');window.scrollTo(0,0);}
    else if(action==='correction')requestDialog('Record a request','Describe a factual correction, accommodation or data request. The local recruiter can inspect it in the application activity log.','Your request',async message=>{const r=await api('/api/candidate/correction',{id:control.dataset.id,message});if(S.application?.id===r.application.id)S.application=r.application;await refresh();toast('Your request is recorded for the local recruiter.');});
    else if(action==='withdraw')requestDialog('Withdraw this application','Your evidence remains available, but the application will no longer be active. Withdrawal does not create an integrity label.','Reason or context',async message=>{const r=await api('/api/candidate/withdraw',{id:control.dataset.id,reason:message});S.application=r.application;renderCandidate();toast('Application withdrawn.');});
    else if(action==='recruiter-nav'){S.view=control.dataset.view;S.application=null;if(S.view==='audit'){S.events=(await api('/api/recruiter/audit')).events;}if(S.view==='settings'){S.ai=await api('/api/recruiter/ai');}S.pool=await api('/api/recruiter');renderRecruiter();window.scrollTo(0,0);}
    else if(action==='recruiter-refresh'){S.pool=await api('/api/recruiter');if(S.view==='detail'&&S.application){const r=await api('/api/application/'+S.application.id);S.application=r.application;}renderRecruiter();toast('Workspace refreshed.');}
    else if(action==='review-candidate')await openReview(control.dataset.id);
    else if(action==='review-tab'){S.reviewTab=control.dataset.tab;renderRecruiter();}
    else if(action==='recruiter-action'){const sid=S.application.id,value=control.dataset.value;requestDialog(value==='invite'?'Invite to the assessment':value==='interview'?'Select for interview':'Close this application','This is your decision. Your reason appears in the local candidate workspace. No email or external invitation is sent.','Reason for the decision',async reason=>{const r=await api('/api/recruiter/action',{id:sid,action:value,reason});S.application={...S.application,...r.application};S.pool=await api('/api/recruiter');renderRecruiter();toast('Decision recorded. The candidate workspace is updated.');});}
    else if(action==='select-job'){S.job=control.dataset.job;S.view='pool';renderRecruiter();}
    else if(action==='check-ai'){busy(control,true);S.ai=await api('/api/recruiter/ai');renderRecruiter();}
    else if(action==='load-audit'){S.events=(await api('/api/recruiter/audit')).events;renderRecruiter();}
    else if(action==='stop-server'){
      const d=$('#dialog');$('#dialog-content').innerHTML='<form id="stop-form" class="stack"><h2>Stop the local server?</h2><p class="muted small">Both workspaces will disconnect. Saved records stay on this computer. Type STOP to confirm.</p><label class="field"><span>Confirmation</span><input name="confirmation" required pattern="STOP" autocomplete="off"></label><div class="row"><button type="button" class="btn secondary" data-action="close-dialog">Cancel</button><button type="submit" class="btn danger">Stop server</button></div></form>';d.showModal();$('#stop-form').onsubmit=async ev=>{ev.preventDefault();try{await api('/api/recruiter/shutdown',{confirmation:new FormData(ev.target).get('confirmation')});d.close();S.user=null;S.application=null;$('#root').innerHTML='<main id="main" class="loading">'+wordmark+'<h1>Local server stopped.</h1><p class="muted">Your saved records are preserved. Open Start_Evidence_Path.bat to return.</p></main>';}catch(ex){toast(ex.message,true);}};
    }
    else if(action==='close-dialog')$('#dialog').close();
    else if(action==='record-video')await toggleRecording(control);
  }catch(ex){toast(ex.message,true);if(control.isConnected&&control.disabled)busy(control,false);}
});

async function toggleRecording(control){
  if(recorder?.state==='recording'){recorder.stop();return;}
  if(!navigator.mediaDevices?.getUserMedia||!window.MediaRecorder)throw new Error('Recording is unavailable in this browser. You can upload a short video instead.');
  await flush();const sid=S.application.id;
  try{recordStream=await navigator.mediaDevices.getUserMedia({video:{width:{ideal:640},height:{ideal:360}},audio:true});}
  catch{throw new Error('Camera or microphone access was not granted. Use text or upload a video instead.');}
  const chunks=[];const mime=MediaRecorder.isTypeSupported('video/webm;codecs=vp8,opus')?'video/webm;codecs=vp8,opus':MediaRecorder.isTypeSupported('video/webm')?'video/webm':'';
  recorder=new MediaRecorder(recordStream,mime?{mimeType:mime}:{});
  const preview=$('#recording-preview');preview.hidden=false;preview.srcObject=recordStream;preview.muted=true;await preview.play();
  recorder.ondataavailable=ev=>{if(ev.data.size)chunks.push(ev.data);};
  recorder.onstop=async()=>{clearTimeout(recordTimeout);recordStream.getTracks().forEach(t=>t.stop());recordStream=null;const ext=recorder.mimeType.includes('mp4')?'mp4':'webm';const file=new File(chunks,`expression-${Date.now()}.${ext}`,{type:recorder.mimeType});if(preview){preview.srcObject=null;preview.muted=false;}control.textContent='Record a short video';const label=$('#recording-status');if(label)label.textContent='Saving recording…';try{await upload(file,'video',sid);if(S.application?.id===sid){renderCandidate();toast('Recording saved locally.');}}catch(ex){toast(ex.message,true);if(label)label.textContent='Upload failed. Try uploading a video file.';}};
  recorder.start(1000);control.textContent='Stop recording';$('#recording-status').textContent='Recording · stops automatically at 90 seconds';recordTimeout=setTimeout(()=>{if(recorder?.state==='recording')recorder.stop();},90000);
}

window.addEventListener('beforeunload',ev=>{if(saveTimer||recorder?.state==='recording'){ev.preventDefault();ev.returnValue='';}});
window.addEventListener('resize',()=>{if(S.user?.role==='recruiter'&&S.view==='dashboard')requestAnimationFrame(drawMap);});
setInterval(async()=>{if(!S.user||document.hidden||$('#dialog').open)return;try{if(S.user.role==='candidate'&&(!S.application||!['draft','invited'].includes(S.application.status))){if(S.application){const r=await api('/api/application/'+S.application.id);if(r.application.revision!==S.application.revision){S.application=r.application;S.step=0;renderCandidate();toast('A recruiter update is available.');}}else{const d=await api('/api/candidate');const old=JSON.stringify(S.applications?.map(a=>[a.id,a.revision]));S.applications=d.applications;if(old!==JSON.stringify(d.applications.map(a=>[a.id,a.revision])))renderCandidate();}}else if(S.user.role==='recruiter'&&S.view==='dashboard'){const d=await api('/api/recruiter');const old=JSON.stringify(S.pool?.applications.map(a=>[a.id,a.revision]));S.pool=d;if(old!==JSON.stringify(d.applications.map(a=>[a.id,a.revision])))renderRecruiter();}}catch{}},12000);
(async()=>{try{S.boot=await api('/api/bootstrap');S.user=S.boot.user;if(S.user)await refresh();else auth();}catch(ex){$('#root').innerHTML=`<main id="main" class="loading">${wordmark}<div class="error">${esc(ex.message)}</div><p>Check that the local server is running, then reload this page.</p></main>`;}})();
